CREATE DATABASE IF NOT EXISTS xxl_job DEFAULT CHARACTER SET utf8mb4; USE xxl_job;CREATE TABLE IF NOT EXISTS xxl_job_group(id int AUTO_INCREMENT PRIMARY KEY, app_name varchar(64), title varchar(12), address_type tinyint DEFAULT 0, address_list text, update_time datetime);CREATE TABLE IF NOT EXISTS xxl_job_info(id int AUTO_INCREMENT PRIMARY KEY, job_group int, job_desc varchar(255), add_time datetime, update_time datetime, author varchar(64), alarm_email varchar(255), schedule_type varchar(50) DEFAULT "NONE", schedule_conf varchar(128), misfire_strategy varchar(50) DEFAULT "DO_NOTHING", executor_route_strategy varchar(50), executor_handler varchar(255), executor_param varchar(512), executor_block_strategy varchar(50), executor_timeout int DEFAULT 0, executor_fail_retry_count int DEFAULT 0, glue_type varchar(50), glue_source mediumtext, glue_remark varchar(128), glue_updatetime datetime, child_jobid varchar(255), trigger_status tinyint DEFAULT 0, trigger_last_time bigint DEFAULT 0, trigger_next_time bigint DEFAULT 0);CREATE TABLE IF NOT EXISTS xxl_job_log(id bigint AUTO_INCREMENT PRIMARY KEY, job_group int, job_id int, executor_address varchar(255), executor_handler varchar(255), executor_param varchar(512), executor_sharding_param varchar(20), executor_fail_retry_count int DEFAULT 0, trigger_time datetime, trigger_code int, trigger_msg text, handle_time datetime, handle_code int, handle_msg text, alarm_status tinyint DEFAULT 0, KEY I_trigger_time(trigger_time), KEY I_handle_code(handle_code));CREATE TABLE IF NOT EXISTS xxl_job_user(id int AUTO_INCREMENT PRIMARY KEY, username varchar(50), password varchar(50), role tinyint, permission varchar(255), UNIQUE KEY i_username(username));CREATE TABLE IF NOT EXISTS xxl_job_lock(lock_name varchar(50) PRIMARY KEY);INSERT IGNORE INTO xxl_job_user VALUES(1,'admin','e10adc3949ba59abbe56e057f20f883e',1,NULL);INSERT IGNORE INTO xxl_job_lock VALUES('schedule_lock');INSERT IGNORE INTO xxl_job_group(app_name,title,address_type) VALUES('tj-agent','tj-agent',0);